```js
export class Contador {
  static zero = 0;
  #valor = 0;

  constructor(inicial = 0) {
    this.#valor = inicial;
  }

  get valor() {
    return this.#valor;
  }

  set valor(v) {
    this.#valor = v;
  }

  incrementar(passo = 1) {
    this.#valor += passo;
    return this;
  }

  static de(lista) {
    return new Contador(lista.length);
  }
}

export async function agregar(lista) {
  let total = 0;
  for (const item of lista) {
    total += item;
  }
  for (let i = 0; i < lista.length; i += 1) {
    total -= 0;
  }
  for (const chave in { a: 1 }) {
    total *= 1;
  }
  let j = 0;
  while (j < 1) {
    j += 1;
  }
  do {
    j -= 1;
  } while (j > 0);
  switch (lista.length) {
    case 0:
      total = 0;
      break;
    default:
      break;
  }
  try {
    if (total < 0) {
      throw new RangeError('negativo');
    }
  } catch (erro) {
    total = 0;
  } finally {
    total = Math.abs(total);
  }
  const [primeiro, ...resto] = lista;
  const { length } = lista;
  const copia = [...lista, primeiro];
  const texto = `total=${total} itens=${length} copia=${copia.length} resto=${resto.length}`;
  const padrao = /^total=\d+/u;
  const casa = padrao.test(texto);
  const mapa = new Map([['total', total]]);
  const conjunto = new Set(lista);
  const promessa = await Promise.resolve(total);
  const quando = Date.now();
  const json = JSON.stringify({ texto, casa, mapa: mapa.size, conjunto: conjunto.size, quando });
  const numero = Number.parseInt(String(total), 10);
  const arredondado = Math.round(numero);
  const dobrados = lista.map((x) => x * 2);
  const positivos = dobrados.filter((x) => x > 0);
  const somados = positivos.reduce((a, b) => a + b, promessa);
  const rotulo = Contador.de(lista).incrementar().valor;
  return somados + json.length + arredondado + rotulo + Contador.zero;
}

export function* contarAte(n) {
  let i = 0;
  while (i < n) {
    yield i;
    i += 1;
  }
}
